import type { OutreachChannel } from "./types";

export interface OutreachApprovalRequest {
  messageId: string;
  candidateId: string;
  channel: OutreachChannel;
  recipient: string;
  subject: string;
  body: string;
}

export type OutreachApprovalPersistence =
  | { ok: true; dryRun: boolean; detail?: string }
  | { ok: false; error: string };

type ApprovalFetch = typeof fetch;

const APPROVAL_NOT_RECORDED = "Approval was not recorded. The draft remains pending.";

/**
 * Persist the exact copy a human approved before the client changes local
 * workflow state. A non-2xx, malformed, or non-confirming response is always
 * treated as a failed approval: never optimistically advance the draft.
 */
export async function recordOutreachApproval(
  request: OutreachApprovalRequest,
  fetcher: ApprovalFetch = fetch,
): Promise<OutreachApprovalPersistence> {
  try {
    const response = await fetcher("/api/outreach/approve", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(request),
    });
    const payload = (await response.json().catch(() => null)) as {
      ok?: unknown;
      status?: unknown;
      persisted?: unknown;
      detail?: unknown;
    } | null;
    if (!response.ok || payload?.ok !== true) {
      return { ok: false, error: APPROVAL_NOT_RECORDED };
    }
    const dryRun = payload.status === "dry-run" && payload.persisted === false;
    return { ok: true, dryRun, detail: dryRun && typeof payload.detail === "string" ? payload.detail : undefined };
  } catch {
    return { ok: false, error: APPROVAL_NOT_RECORDED };
  }
}

/**
 * Revoke a recorded approval before the durable delivery claim begins. The
 * server returns success for a missing/already-revoked row, but rejects the
 * explicit send cutoff so the UI never says a live message was cancelled.
 */
export async function revokeOutreachApproval(
  messageId: string,
  fetcher: ApprovalFetch = fetch,
): Promise<OutreachApprovalPersistence> {
  try {
    const response = await fetcher("/api/outreach/revoke", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ messageId }),
    });
    const payload = (await response.json().catch(() => null)) as {
      ok?: unknown;
      status?: unknown;
      persisted?: unknown;
      detail?: unknown;
    } | null;
    if (!response.ok || payload?.ok !== true) {
      return { ok: false, error: "Approval could not be revoked. The draft remains unchanged." };
    }
    const dryRun = payload.status === "dry-run" && payload.persisted === false;
    return { ok: true, dryRun, detail: dryRun && typeof payload.detail === "string" ? payload.detail : undefined };
  } catch {
    return { ok: false, error: "Approval could not be revoked. The draft remains unchanged." };
  }
}

create or replace function public.record_outreach_approval(
  p_message_id text,
  p_body_hash text,
  p_approval_scope_hash text
) returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  wid uuid := public.current_workspace_id();
  role_name text := public.current_profile_role();
  approval public.outreach_approvals%rowtype;
begin
  if auth.uid() is null then return json_build_object('ok', false, 'reason', 'not-authenticated'); end if;
  if role_name not in ('admin', 'member') then return json_build_object('ok', false, 'reason', 'insufficient-permissions'); end if;
  if wid is null then return json_build_object('ok', false, 'reason', 'workspace-not-found'); end if;
  if p_message_id is null or length(p_message_id) < 1 or length(p_message_id) > 120 then
    return json_build_object('ok', false, 'reason', 'invalid-message-id');
  end if;
  if p_body_hash is null or p_approval_scope_hash is null
    or p_body_hash !~ '^[0-9a-f]{64}$' or p_approval_scope_hash !~ '^[0-9a-f]{64}$' then
    return json_build_object('ok', false, 'reason', 'invalid-approval-hash');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(wid::text || ':' || p_message_id, 0));

  select * into approval
    from public.outreach_approvals
    where workspace_id = wid and message_id = p_message_id
    for update;

  -- Re-check after locking the approval.  Otherwise a waiting record request
  -- can overwrite the approval that a completed claim just bound to the ledger.
  if exists (
    select 1 from public.outreach_ledger l
      where l.workspace_id = wid
        and l.approval_message_id = p_message_id
        and l.status in ('claimed', 'sent')
  ) then
    return json_build_object('ok', false, 'reason', 'already-dispatching');
  end if;

  if found then
    update public.outreach_approvals
      set body_hash = p_body_hash,
          approval_scope_hash = p_approval_scope_hash,
          approved_by = auth.uid(),
          approved_at = now(),
          approval_source = 'human',
          revoked_at = null,
          revoked_by = null,
          revocation_reason = null
      where id = approval.id;
  else
    insert into public.outreach_approvals(
      workspace_id,
      message_id,
      body_hash,
      approval_scope_hash,
      approved_by,
      approved_at,
      approval_source,
      revoked_at,
      revoked_by,
      revocation_reason
    ) values (
      wid,
      p_message_id,
      p_body_hash,
      p_approval_scope_hash,
      auth.uid(),
      now(),
      'human',
      null,
      null,
      null
    ) on conflict (workspace_id, message_id) do nothing;

    select * into approval
      from public.outreach_approvals
      where workspace_id = wid and message_id = p_message_id
      for update;
    if not found then return json_build_object('ok', false, 'reason', 'approval-record-failed'); end if;

    -- The conflict path is only reachable for a legacy/direct writer.  Check
    -- again after taking its row lock before allowing any mutation.
    if exists (
      select 1 from public.outreach_ledger l
        where l.workspace_id = wid
          and l.approval_message_id = p_message_id
          and l.status in ('claimed', 'sent')
    ) then
      return json_build_object('ok', false, 'reason', 'already-dispatching');
    end if;

    update public.outreach_approvals
      set body_hash = p_body_hash,
          approval_scope_hash = p_approval_scope_hash,
          approved_by = auth.uid(),
          approved_at = now(),
          approval_source = 'human',
          revoked_at = null,
          revoked_by = null,
          revocation_reason = null
      where id = approval.id;
  end if;

  return json_build_object('ok', true);
end;
$$;

